<script>
  import { onMount, tick } from 'svelte';
  import WindowControls from './WindowControls.svelte';
  import { weatherAppMeta, weatherAppWindow, weatherSearch, weatherDisplayedRow, weatherSource, weatherTemperatureUnit, weatherTemperature, weatherConditionLabel, weatherConditionSymbol, weatherMetrics, weatherLocationPermission, weatherMapPoints, weatherForecastChart, weatherSceneEpoch } from './weather-app-state.js';
  import { weatherAppMenus } from './weather-app-commands.js';
  import { createWeatherAppNativeView } from './weather-app-native-view.js';
  let { state: nativeWeatherState, profile, windowId, window: nativeWindow = null, widgets, preferences, sceneTime, systemClock = null, execute, registerView, available = true, active = true, controls = {} } = $props();
  let root = $state(null), message = $state(''), chartPoint = $state(null);
  let originalState, originalProfile, originalWindowId, originalWindow, retired = false, favoriteDrag = null, mapDrag = null;
  const session = $derived(weatherAppWindow(nativeWeatherState, windowId));
  const meta = $derived(weatherAppMeta(profile));
  const windows = $derived(profile.id.startsWith('windows11'));
  const classic = $derived(/high-sierra|mojave/u.test(profile.id));
  const golden = $derived(profile.id.includes('golden-gate'));
  const row = $derived(weatherDisplayedRow(widgets, session));
  const metrics = $derived(weatherMetrics(row));
  const unit = $derived(weatherTemperatureUnit(widgets, preferences));
  const searchRows = $derived(weatherSearch(widgets, session?.query ?? ''));
  const menus = $derived(weatherAppMenus(profile, nativeWeatherState, windowId, widgets, preferences));
  const time = $derived(weatherSceneEpoch(sceneTime) ?? weatherSceneEpoch(profile.defaults.sceneTime) ?? 0);
  const mapFrame = $derived(session?.mapPlaying ? (session.mapIndex + Math.floor(time / 2000)) % 24 : session?.mapIndex ?? 0);
  const mapPoints = $derived(weatherMapPoints(widgets, { ...session, mapIndex: mapFrame }, time));
  const chart = $derived(weatherForecastChart(row, unit));
  const dailyLow = $derived(row ? Math.min(row.low, ...row.daily.map(day => day.low)) : 0);
  const dailyHigh = $derived(row ? Math.max(row.high, ...row.daily.map(day => day.high)) : 1);
  const metricCards = $derived(metrics ? [
    { id: 'temperature', title: 'FEELS LIKE', value: `${weatherTemperature(row.temperature, unit)}°`, note: 'Original fixture temperature; no inferred wind chill.' },
    { id: 'uv', title: 'UV INDEX', value: metrics.uv, note: 'Illustrative · derived from cloud cover' },
    { id: 'wind', title: 'WIND', value: `${metrics.wind} km/h`, note: 'Illustrative · high/low spread + condition' },
    { id: 'precipitation', title: 'PRECIPITATION', value: `${metrics.precipitation} mm`, note: 'Illustrative · original condition' },
    { id: 'humidity', title: 'HUMIDITY', value: `${metrics.humidity}%`, note: 'Illustrative · original condition' },
    { id: 'visibility', title: 'VISIBILITY', value: `${metrics.visibility} km`, note: 'Illustrative · original condition' },
    { id: 'pressure', title: 'PRESSURE', value: `${metrics.pressure} hPa`, note: 'Illustrative · original high/low spread' },
  ] : []);
  function owned() { return !retired && root?.isConnected === true && nativeWeatherState === originalState && profile === originalProfile && windowId === originalWindowId && nativeWindow === originalWindow; }
  async function command(suffix, payload = {}) {
    if (!owned() || !available || !active) return;
    const result = await execute(`weather.${suffix}`, { windowId }, payload);
    if (owned()) message = result?.status === 'applied' ? '' : result?.error?.message ?? 'The original Weather operation is unavailable.';
    return result;
  }
  const temp = value => `${weatherTemperature(value, unit)}°`;
  function date(offset, zone, kind = 'hour') {
    const at = time + offset * (kind === 'hour' ? 3600000 : 86400000);
    if (!Number.isSafeInteger(at) || at < 0 || at > 8639999999999999) return `+${offset} ${kind === 'hour' ? 'h' : 'days'}`;
    return new Intl.DateTimeFormat('en-US', kind === 'hour' ? { hour: 'numeric', hour12: !systemClock?.use24Hour, timeZone: zone } : { weekday: 'short', timeZone: zone }).format(at);
  }
  function reorder(id, amount) {
    const ids = widgets.sources.weather.map(row => row.id), index = ids.indexOf(id), destination = index + amount;
    if (destination < 0 || destination >= ids.length) return;
    [ids[index], ids[destination]] = [ids[destination], ids[index]];
    command('favorite.reorder', { locationIds: ids });
  }
  function dragFavorite(event, source) {
    if (!owned() || !session?.editing || session.query) { event.preventDefault(); return; }
    favoriteDrag = { source, widgets, session, rows: [...widgets.sources.weather] };
    event.dataTransfer.effectAllowed = 'move'; event.dataTransfer.setData('text/plain', source.id);
  }
  function dropFavorite(event, destination) {
    event.preventDefault();
    const drag = favoriteDrag; favoriteDrag = null;
    if (!drag || !owned() || !session.editing || drag.widgets !== widgets || drag.session !== session || drag.rows.length !== widgets.sources.weather.length || drag.rows.some((row, index) => row !== widgets.sources.weather[index]) || weatherSource(widgets, drag.source.id) !== drag.source) return;
    const ids = widgets.sources.weather.map(row => row.id), from = ids.indexOf(drag.source.id), to = ids.indexOf(destination.id);
    if (from < 0 || to < 0 || from === to) return;
    ids.splice(from, 1); ids.splice(to, 0, drag.source.id); command('favorite.reorder', { locationIds: ids });
  }
  function mapStart(event) {
    if (!owned() || !active || !available || event.target.closest('[data-weather-control]')) return;
    mapDrag = { session, widgets, root, pointer: event.pointerId, x: event.clientX, y: event.clientY, panX: session.mapX, panY: session.mapY };
    event.currentTarget.setPointerCapture(event.pointerId);
  }
  function mapEnd(event) {
    const drag = mapDrag; mapDrag = null;
    if (!drag || !owned() || drag.root !== root || drag.widgets !== widgets || drag.session !== session || drag.pointer !== event.pointerId) return;
    command('map.pan', { x: Math.max(-300, Math.min(300, Math.round(drag.panX + event.clientX - drag.x))), y: Math.max(-200, Math.min(200, Math.round(drag.panY + event.clientY - drag.y))) });
  }
  function key(event) {
    if (!owned() || !available || !active) return;
    if (event.key === 'Escape') { if (session.detail) command('detail', { detail: null }); else if (session.menu) command('menu', { menu: null }); else if (session.section !== 'forecast') command('section', { section: 'forecast' }); else if (session.query) command('search', { query: '' }); }
    if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'f') { event.preventDefault(); command('native.focus', { controlId: 'search' }); }
  }
  onMount(() => {
    originalState = nativeWeatherState; originalProfile = profile; originalWindowId = windowId; originalWindow = nativeWindow;
    const view = createWeatherAppNativeView({ getRoot: () => root, getState: () => nativeWeatherState, getWidgets: () => widgets, getPreferences: () => preferences, windowId, available: () => owned() && available && active, tick, getMenus: () => weatherAppMenus(profile, nativeWeatherState, windowId, widgets, preferences) });
    registerView(windowId, view);
    return () => { retired = true; favoriteDrag = null; mapDrag = null; view.destroy(); registerView(originalWindowId, null, view); };
  });
</script>

{#snippet conditionArt(condition)}
  <svg class="condition-art" class:storm={condition === 'storm'} class:wet={condition === 'rain'} class:snow={condition === 'snow'} class:fog={condition === 'fog'} viewBox="0 0 600 220" aria-hidden="true">
    {#if condition === 'sunny' || condition === 'partly-cloudy'}<g class="sun"><circle cx="435" cy="60" r="35" fill="#fff3b5"/><circle cx="435" cy="60" r="62" fill="#fff7d6" opacity=".09"/><circle cx="435" cy="60" r="92" fill="#fff7d6" opacity=".05"/></g>{/if}
    {#if condition !== 'sunny' && condition !== 'fog'}<g class="clouds" fill="white" opacity={condition === 'storm' ? '.22' : '.3'}><path d="M32 104 Q22 78 47 68 Q44 35 75 32 Q111 10 137 40 Q173 40 175 69 Q196 72 189 104Z"/><path d="M355 130 Q344 102 372 93 Q368 61 399 60 Q427 38 455 67 Q487 64 491 97 Q514 103 510 130Z"/></g>{/if}
    {#if condition === 'rain' || condition === 'storm'}<g class="rain" stroke="#cae6ff" stroke-width="2" opacity=".6">{#each [60,100,146,184,252,318,390,445,499,557] as x}<path d={`M${x} 133 l-10 28 M${x + 15} 185 l-8 23`}/>{/each}</g>{/if}
    {#if condition === 'snow'}<g class="snowflakes" fill="white" opacity=".75">{#each [60,130,210,290,370,450,540] as x}<circle cx={x} cy={135 + x % 45} r="3"/><circle cx={x + 15} cy={200 - x % 30} r="2"/>{/each}</g>{/if}
    {#if condition === 'storm'}<path class="lightning" d="M421 107 l-22 43 h20 l-16 45 42-55 h-22 l16-33Z" fill="#fff1be"/>{/if}
    {#if condition === 'fog'}<g class="mist" stroke="white" stroke-width="16" stroke-linecap="round" opacity=".12"><path d="M-30 67 H490 M120 110 H660 M-60 153 H410 M210 196 H680"/></g>{/if}
  </svg>
{/snippet}

{#snippet mapArt(expanded)}
  <svg class="weather-map" class:expanded viewBox="0 0 600 380" role="img" aria-label={`Schematic authored ${session.mapLayer} map; original shared favorite locations; not geographic or radar data`} onpointerdown={expanded ? mapStart : undefined} onpointerup={expanded ? mapEnd : undefined} onpointercancel={() => { mapDrag = null; }}>
    <rect width="600" height="380" fill="#b8d2df"/>
    <g transform={`translate(${session.mapX} ${session.mapY}) translate(300 190) scale(${session.mapZoom}) translate(-300 -190)`}>
      <path d="M18 49 L71 28 L130 41 L174 23 L222 57 L210 113 L177 131 L174 166 L217 192 L197 222 L177 206 L149 153 L96 151 L63 109 L27 99Z M171 226 L219 223 L245 255 L233 298 L200 350 L188 302 L161 262Z M261 85 L282 47 L329 54 L355 72 L416 55 L450 87 L510 92 L559 123 L530 168 L485 174 L473 225 L441 205 L410 161 L359 170 L347 146 L312 158 L282 119Z M282 170 L330 158 L363 202 L344 256 L312 284 L296 235 L265 203Z M458 278 L509 265 L551 294 L534 327 L480 335Z" fill="#e8eade" stroke="#a2b7ad" stroke-width="1.5"/>
      <g stroke="#a8b9a5" fill="none" opacity=".55"><path d="M86 81 Q131 98 180 68 M107 131 L173 119 M295 96 L386 113 L470 120 M307 190 L334 213 M480 300 L523 306"/><path d="M50 87 L113 110 L169 91 M359 75 L380 136 L440 147" stroke-dasharray="4 5"/></g>
      {#each mapPoints as point (point.row.id)}
        {#if session.mapLayer === 'precipitation' && point.metrics.precipitation > 0}<ellipse class:map-cloud-moving={session.mapPlaying} cx={point.x} cy={point.y} rx={25 + point.metrics.precipitation * 2} ry="28" fill={point.condition === 'storm' ? '#d9973c' : point.condition === 'snow' ? '#d9edf4' : '#4c8bc8'} opacity=".45"/>{/if}
        {#if session.mapLayer === 'temperature'}<circle cx={point.x} cy={point.y} r="31" fill={point.temperature < 0 ? '#779fd8' : point.temperature < 16 ? '#72ba9b' : '#e9bc63'} opacity=".3"/>{/if}
        {#if session.mapLayer === 'wind'}<path d={`M${point.x - 26} ${point.y + 12} q20 -28 46 -8 l-9 -2 m9 2 l-5 -8`} fill="none" stroke="#3385a8" stroke-width="3"/>{/if}
        <g class="map-pin" role="button" tabindex="0" data-weather-control={`map:${point.row.id}`} data-weather-location={point.row.id} aria-label={`View ${point.row.name}`} onclick={() => command('select', { locationId: point.row.id })} onkeydown={event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); command('select', { locationId: point.row.id }); } }}>
          <circle cx={point.x} cy={point.y} r="15" fill={widgets.selected.weatherLocationId === point.row.id ? '#1364a2' : '#fff'} stroke="#2277a9" stroke-width="2"/>
          <text x={point.x} y={point.y + 4} text-anchor="middle" fill={widgets.selected.weatherLocationId === point.row.id ? '#fff' : '#184963'} font-size="11" font-weight="600">{session.mapLayer === 'temperature' ? temp(point.temperature) : session.mapLayer === 'wind' ? point.metrics.wind : point.metrics.precipitation}</text>
          <text x={point.x} y={point.y + 30} text-anchor="middle" fill="#1b3e51" font-size="11" font-weight="600" paint-order="stroke" stroke="#e8eade" stroke-width="3">{point.row.name}</text>
        </g>
      {/each}
    </g>
  </svg>
{/snippet}

<section bind:this={root} class="weather-app" class:windows class:classic class:golden class:inactive={!active} class:rainy={row?.condition === 'rain'} class:stormy={row?.condition === 'storm'} class:snowy={row?.condition === 'snow'} class:foggy={row?.condition === 'fog'} data-weather-window-id={windowId} data-profile={profile.id} role="region" aria-label={meta.name} tabindex="-1" onkeydown={key}>
  <header class="titlebar">
    {#if !windows}<WindowControls active={active} onclose={() => command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} onsplitbegin={controls.onsplitbegin} onsplitside={controls.onsplitside} ongreenmenu={controls.ongreenmenu} fullScreen={controls.fullScreen} revealedTop={controls.revealedTop} modernGreenMenu={controls.modernGreenMenu} zoomed={controls.zoomed}/>{/if}
    <button class="sidebar-toggle" title="Show or hide locations" aria-label="Show or hide locations" aria-pressed={session?.sidebar} data-weather-control="sidebar" onclick={() => command('sidebar', { visible: !session.sidebar })}>▥</button>
    {#if windows || classic}<strong>{meta.name}</strong>{/if}
    <div class="toolbar-spacer"></div>
    {#if session?.previewId}<button data-weather-control="favorite:add" disabled={!!weatherSource(widgets, session.previewId)} onclick={() => command('favorite.add', { locationId: session.previewId })}>{weatherSource(widgets, session.previewId) ? '✓ Added' : '＋ Add'}</button>{/if}
    <label class="search-field"><span aria-hidden="true">⌕</span><input type="search" placeholder="Search" maxlength="512" value={session?.query ?? ''} aria-label="Search authored weather locations" data-weather-control="search" oninput={event => command('search', { query: event.currentTarget.value })}/></label>
    {#if windows}<div class="windows-controls"><button aria-label="Minimize" onclick={controls.onminimize}>—</button><button aria-label="Maximize" onclick={controls.onzoom}>□</button><button aria-label="Close" data-weather-control="close" onclick={() => command('window.close')}>×</button></div>{/if}
  </header>
  <nav class="local-menubar" aria-label="Weather application menus">{#each menus as menu}<button data-weather-control={`menu:${menu.id}`} aria-haspopup="menu" aria-expanded={session?.menu === menu.id} onclick={() => command('menu', { menu: session?.menu === menu.id ? null : menu.id })}>{menu.label}</button>{/each}</nav>
  {#if session?.menu}<div class="menu-popover" role="menu" aria-label={session.menu}>{#each menus.find(menu => menu.id === session.menu)?.items ?? [] as item}<button role="menuitem" data-weather-control={`menuitem:${item.id}`} disabled={!item.enabled} onclick={async () => { const result = await command('menu', { menu: null }); if (result?.status === 'applied') command(item.request.command.slice('weather.'.length), item.request.payload); }}>{item.checked ? '✓ ' : ''}{item.label}</button>{/each}</div>{/if}
  {#if meta.localEquivalent || golden}<div class="era-disclosure">{meta.disclosure}</div>{/if}
  <div class="workspace" inert={!available || !active || !!session?.detail && !!row}>
    {#if session?.sidebar}<aside class="sidebar">
      <button class="my-location" data-weather-control="currentLocation" onclick={() => command('currentLocation')}><span>⌖ My Location</span><small>{weatherLocationPermission(preferences) ? 'Authored Pine Valley scene location' : 'Location access off — enable in Privacy & Security'}</small></button>
      {#if session.query}<div class="sidebar-caption">AUTHORED SEARCH RESULTS</div><div class="favorites" data-weather-area="favorites">{#each searchRows as source (source.id)}<button class="search-result" data-weather-control={`result:${source.id}`} data-weather-location={source.id} onclick={() => command(weatherSource(widgets, source.id) ? 'select' : 'preview', { locationId: source.id })}><strong>{source.name}</strong><span>{weatherSource(widgets, source.id) ? 'Saved location' : 'Preview authored forecast'}</span></button>{:else}<p class="empty-search">No authored locations match “{session.query}”. Try Pine, Harbor, Maple, Snow, Misty or Storm.</p>{/each}</div>
      {:else}<div class="sidebar-caption">MY LOCATIONS</div><div class="favorites" data-weather-area="favorites">{#each widgets.sources.weather as source, index (source.id)}<div class="favorite" class:selected={widgets.selected.weatherLocationId === source.id && !session.previewId} draggable={session.editing} ondragstart={event => dragFavorite(event, source)} ondragover={event => { if (favoriteDrag) event.preventDefault(); }} ondrop={event => dropFavorite(event, source)} ondragend={() => { favoriteDrag = null; }}><button class="favorite-select" data-weather-control={`location:${source.id}`} data-weather-location={source.id} onclick={() => command('select', { locationId: source.id })}><span><strong>{source.name}</strong><small>{date(0, source.timeZone)} · {weatherConditionLabel(source.condition)}</small></span><b>{temp(source.temperature)}</b><small>H:{temp(source.high)} L:{temp(source.low)}</small></button>{#if session.editing}<div class="favorite-actions"><button aria-label={`Move ${source.name} up`} disabled={index === 0} data-weather-control={`up:${source.id}`} onclick={() => reorder(source.id, -1)}>↑</button><button aria-label={`Move ${source.name} down`} disabled={index === widgets.sources.weather.length - 1} data-weather-control={`down:${source.id}`} onclick={() => reorder(source.id, 1)}>↓</button><button aria-label={`Remove ${source.name}`} data-weather-control={`remove:${source.id}`} onclick={() => command('favorite.remove', { locationId: source.id })}>Delete</button></div>{/if}</div>{:else}<p class="empty-search">Your location list is empty. Search for an authored city and choose Add.</p>{/each}</div>{/if}
      <footer class="sidebar-footer"><button data-weather-control="favorite:edit" onclick={() => command('favorite.edit', { editing: !session.editing })}>{session.editing ? 'Done' : 'Edit Locations'}</button><span>°<button class:chosen={unit === 'celsius'} data-weather-control="unit:celsius" onclick={() => command('unit', { unit: 'celsius' })}>C</button> / °<button class:chosen={unit === 'fahrenheit'} data-weather-control="unit:fahrenheit" onclick={() => command('unit', { unit: 'fahrenheit' })}>F</button></span></footer>
    </aside>{/if}
    <main class="content" data-weather-area={session?.section === 'help' ? 'help' : 'forecast'}>
      {#if session?.section === 'settings'}<section class="settings-panel"><h1>Weather Settings</h1><h2>Temperature units</h2><p>{widgets.instances.some(row => row.kind === 'weather') ? 'The first original Weather widget determines the displayed unit. A change updates every shared Weather widget, preserving their original location references.' : 'No Weather widgets exist. Units use the actual Language & Region temperature preference, not a duplicate Weather setting.'}</p><div class="unit-options">{#each ['celsius', 'fahrenheit'] as value}<button class:chosen={unit === value} data-weather-control={`settings:${value}`} aria-pressed={unit === value} onclick={() => command('unit', { unit: value })}>{value === 'celsius' ? 'Celsius (°C)' : 'Fahrenheit (°F)'}</button>{/each}</div><h2>Location access</h2><p>{weatherLocationPermission(preferences) ? 'Enabled in the actual Weather location permission.' : 'Disabled. Set Weather’s location permission in Privacy & Security.'} My Location selects the authored fictional Pine Valley scene location. The app never reads host GPS or your physical location.</p><button data-weather-control="settings:back" onclick={() => command('section', { section: 'forecast' })}>Done</button></section>
      {:else if session?.section === 'help'}<article class="help-panel"><h1>Weather</h1><p>{meta.disclosure}</p><h2>One forecast source</h2><p>Favorites are the actual shared widget weather rows. Selection is shared with every Weather window and widget host. Search uses seven authored fictional cities. Previewing a city does not save it; Add creates a compatible original source record. Delete retargets widgets and selection to the first remaining favorite, or clears their references when the list becomes empty.</p><h2>Forecasts, maps and details</h2><p>Temperature, high/low, condition, hourly and daily rows are authored offline forecasts, not live weather. Existing shared rows are displayed without rewriting them. The number of forecast days and hours is exactly what those rows contain; a seven-day fixture is never called a ten-day forecast.</p><p>The interactive SVG map is a schematic fictional atlas, not a geographic basemap or radar. Temperature pins use actual hourly forecasts. Precipitation and wind overlays use the disclosed illustrative derived condition metrics. Pan by dragging, zoom with +/−, choose a layer, or select a time. Playback is driven only by the authored scene clock; a paused scene pauses the forecast progression.</p><p>UV, humidity, visibility, wind, pressure and precipitation details are disclosed illustrative calculations. We do not invent observations, government alerts, air-quality readings, live service connections or Apple ID synchronization.</p><h2>Controls</h2><p>Search: Command/Control-F. Escape closes details and menus, returns to the forecast, or clears search. Edit Locations exposes Delete, Move Up and Move Down; dragging reorders the same shared source list.</p><h2>Research</h2><p>Sonoma 14 uses Apple’s versioned Weather user guide. Golden Gate uses the nearest researched Tahoe 26 reference, not certified 27 pixels. High Sierra, Mojave and Windows use explicitly labeled local equivalents.</p><button data-weather-control="help:back" onclick={() => command('section', { section: 'forecast' })}>Back to Weather</button></article>
      {:else if session?.section === 'map'}<section class="expanded-map"><header><h1>Weather Map</h1><button data-weather-control="map:close" onclick={() => command('section', { section: 'forecast' })}>Done</button></header><div class="map-tools">{#each ['temperature', 'precipitation', 'wind'] as layer}<button class:chosen={session.mapLayer === layer} data-weather-control={`map:layer:${layer}`} aria-pressed={session.mapLayer === layer} onclick={() => command('map.layer', { layer })}>{layer}</button>{/each}<button disabled={session.mapZoom === 1} data-weather-control="map:zoom-out" aria-label="Zoom out" onclick={() => command('map.zoom', { zoom: session.mapZoom - 1 })}>−</button><button disabled={session.mapZoom === 4} data-weather-control="map:zoom-in" aria-label="Zoom in" onclick={() => command('map.zoom', { zoom: session.mapZoom + 1 })}>＋</button><button data-weather-control="map:reset" onclick={async () => { await command('map.pan', { x: 0, y: 0 }); command('map.zoom', { zoom: 1 }); }}>Center</button></div>{@render mapArt(true)}<div class="map-timeline"><button data-weather-control="map:play" aria-pressed={session.mapPlaying} onclick={() => command('map.play', { playing: !session.mapPlaying })}>{session.mapPlaying ? 'Pause' : 'Play'}</button><label>Forecast sample {mapFrame + 1}<input type="range" min="0" max="23" step="1" value={mapFrame} aria-label="Forecast sample" data-weather-control="map:time" oninput={event => command('map.time', { index: Number(event.currentTarget.value) })}/></label></div><p class="map-disclosure">Schematic authored atlas · {session.mapLayer === 'temperature' ? 'original shared hourly Celsius forecasts converted to the selected unit' : 'illustrative condition-derived values, not radar or measured wind'}. Shorter original forecasts retain their last sample. No network, geographic or physical-location data.</p></section>
      {:else if row}<div class="condition-scene">{@render conditionArt(row.condition)}</div><section class="current-weather"><h1>{row.name}</h1><div class="current-temperature">{temp(row.temperature)}</div><strong>{weatherConditionLabel(row.condition)}</strong><p>H:{temp(row.high)} &nbsp; L:{temp(row.low)}</p>{#if session?.previewId}<small>Authored catalogue preview · not saved</small>{/if}</section>
        <section class="weather-card hourly-card"><h2>{weatherConditionLabel(row.condition)} conditions in the original authored forecast.</h2><div class="hourly-strip" data-weather-area="hourly">{#each row.hourly as hour, index}<button class="hour" data-weather-control={`hour:${index}`} title={`${date(hour.offsetHours, row.timeZone)}: ${weatherConditionLabel(hour.condition)}, ${temp(hour.temperature)}`} onclick={() => { chartPoint = index; command('detail', { detail: 'temperature' }); }}><span>{hour.offsetHours === 0 ? 'Now' : date(hour.offsetHours, row.timeZone)}</span><b aria-label={weatherConditionLabel(hour.condition)}>{weatherConditionSymbol(hour.condition)}</b><strong>{temp(hour.temperature)}</strong></button>{:else}<p>No authored hourly rows.</p>{/each}</div></section>
        <div class="forecast-grid"><section class="weather-card daily-card"><h2>▤ {row.daily.length}-DAY FORECAST</h2>{#each row.daily as day}<div class="daily-row" title={`${weatherConditionLabel(day.condition)}; high ${temp(day.high)}, low ${temp(day.low)}`}><strong>{day.offsetDays === 0 ? 'Today' : date(day.offsetDays, row.timeZone, 'day')}</strong><span aria-label={weatherConditionLabel(day.condition)}>{weatherConditionSymbol(day.condition)}</span><span class="low">{temp(day.low)}</span><div class="range-track"><span style={`left:${Math.max(0, (day.low - dailyLow) / Math.max(1, dailyHigh - dailyLow) * 100)}%;width:${Math.max(2, (day.high - day.low) / Math.max(1, dailyHigh - dailyLow) * 100)}%`}></span></div><strong>{temp(day.high)}</strong></div>{:else}<p>No authored daily rows.</p>{/each}</section><button class="weather-card map-card" data-weather-control="map:open" onclick={() => command('section', { section: 'map' })}><h2>⌖ WEATHER MAP</h2><div class="map-thumbnail" inert>{@render mapArt(false)}</div><small>Interactive authored atlas · not radar</small></button>{#each metricCards as metric}<button class="weather-card metric-card" data-weather-control={`detail:${metric.id}`} onclick={() => { chartPoint = null; command('detail', { detail: metric.id }); }}><h2>{metric.title}</h2><strong>{metric.value}</strong><p>{metric.note}</p>{#if metric.id === 'uv'}<div class="uv-bar"><span style={`left:${metrics.uv / 11 * 100}%`}></span></div>{/if}{#if metric.id === 'wind'}<div class="wind-compass" aria-hidden="true">N<span>↗</span>S</div>{/if}</button>{/each}</div>
        <p class="source-note">Authored offline conditions · original shared widget source · {row.timeZone}. Additional details are illustrative derived fixture metrics.</p>
      {:else}<section class="empty-state"><h1>Weather</h1><p>No location selected. Choose a saved location or search an authored city and add it to your list.</p><button data-weather-control="empty:search" onclick={() => command('native.focus', { controlId: 'search' })}>Find a Location</button></section>{/if}
    </main>
  </div>
  {#if session?.detail && row}<div class="detail-backdrop"><section class="detail-sheet" role="dialog" aria-modal="true" aria-label={`${session.detail} details`}><header><h2>{session.detail === 'temperature' ? 'Temperature' : metricCards.find(metric => metric.id === session.detail)?.title} · {row.name}</h2><button data-weather-control="detail:close" aria-label="Close details" onclick={() => command('detail', { detail: null })}>×</button></header><strong class="detail-value">{metricCards.find(metric => metric.id === session.detail)?.value}</strong><p>{session.detail === 'temperature' ? 'Original authored hourly Celsius temperatures, converted only for display.' : metrics.disclosure}</p><h3>Original hourly temperature context</h3><svg class="detail-chart" viewBox="0 0 500 150" role="img" aria-label="Original authored hourly temperature chart"><path d="M12 28 H488 M12 73 H488 M12 118 H488" stroke="white" stroke-opacity=".16"/><path d={chart.path} fill="none" stroke="#ffd589" stroke-width="3"/>{#each chart.points as point, index}<circle cx={point.x} cy={point.y} r={chartPoint === index ? 6 : 3} fill={chartPoint === index ? 'white' : '#ffd589'}/>{/each}</svg><label>Inspect original hour<input data-weather-control="detail:hour" type="range" min="0" max={Math.max(0, chart.points.length - 1)} step="1" disabled={!chart.points.length} value={chartPoint ?? 0} oninput={event => { chartPoint = Number(event.currentTarget.value); }}/></label>{#if chart.points[chartPoint ?? 0]}{@const point = chart.points[chartPoint ?? 0]}<p>{date(point.offsetHours, row.timeZone)} · {point.label} · {weatherConditionLabel(point.condition)}</p>{:else}<p>No original hourly forecast rows.</p>{/if}<p class="fixture-detail">Illustrative details do not become forecast authority. No measurements, alerts, physical location or live provider requests are manufactured.</p></section></div>{/if}
  <footer class="status" role="status">{message || 'Fictional authored forecast · one shared widget graph · no live weather service'}</footer>
</section>

